function createSector(name2, beatNo, pincode = "324009", subOffice = "Dadabari S.O.", description = "") {
  const staff = getStaff(beatNo);
  const cleanBeatNo = beatNo.replace(/\D/g, "") || "2";
  return {
    id: `${name2.toLowerCase().replace(/[^a-z0-9]/g, "-")}-${cleanBeatNo}`,
    name: name2,
    beatNo,
    cleanBeatNo,
    pincode,
    subOffice,
    staffId: staff.id,
    staffName: staff.name,
    staffRole: staff.role,
    staffContact: staff.contact,
    description
  };
}
