  if (cleanPrompt.includes("dashboard") || cleanPrompt.includes("home") || cleanPrompt.includes("डैशबोर्ड")) {
    return {
      message: "Navigating to the Postal Operations Dashboard.",
      action: { type: "NAVIGATE", targetPath: "/dashboard" }
    };
  }
  if (cleanPrompt.includes("customer") && (cleanPrompt.includes("list") || cleanPrompt.includes("directory") || cleanPrompt.includes("view") || cleanPrompt.includes("show"))) {
    return {
      message: "Navigating to the Master Customer Directory.",
      action: { type: "NAVIGATE", targetPath: "/customers" }
    };
  }
  if (cleanPrompt.includes("task") || cleanPrompt.includes("duty") || cleanPrompt.includes("कार्य")) {
    return {
      message: "Navigating to Field Operations & Daily Beat Tasks.",
      action: { type: "NAVIGATE", targetPath: "/tasks" }
    };
  }
